function deduplicateRibbonSubpaths(paths: string[]): string[] {
  const seenStartPoints = new Set<string>();
  const result: string[] = [];

  paths.forEach((pStr) => {
    const match = pStr.match(/^M\s*([\d\.-]+)\s*,\s*([\d\.-]+)/i);
    if (match) {
      const key = `${parseFloat(match[1]).toFixed(2)},${parseFloat(match[2]).toFixed(2)}`;
      if (!seenStartPoints.has(key)) {
        seenStartPoints.add(key);
        result.push(pStr);
      }
    } else {
      result.push(pStr);
    }
  });

  return result;
}

const generateFlowerTemplates = (count: number): MandalaTemplate[] => {
  const templates: MandalaTemplate[] = [];

  const adjectives = mandalaNamesKo.flowers.adjectives;

  for (let idx = 1; idx <= count; idx++) {
    const fItem = FLOWER_SVG_DATA_15[(idx - 1) % FLOWER_SVG_DATA_15.length] || { flowerName: "연꽃", transform: "translate(31.30, 32.79) scale(0.3936)", subpaths: [] };
    const adj = adjectives[(idx - 1) % adjectives.length];
    const flowerName = (fItem.flowerName || "연꽃").replace(/\s*\d+$/, '');
    const id = `flower_${idx}`;
    const shortTitle = `${adj} ${flowerName}`;
    const title = shortTitle;
    const desc = `1번째 온실에서 내면의 평화와 감정을 정화하는 ${adj} ${flowerName} 꽃 도안 (no. ${idx})`;

    const rawPaths = fItem.subpaths || [];
    const validPaths = rawPaths.filter(pStr => pStr.startsWith("M") || pStr.startsWith("m"));

    // Disaggregate compound SVG paths into individual sub-paths for 100% fine-grained touch coloring
    const allDisaggregatedSubpaths: string[] = [];
    validPaths.forEach((pathStr) => {
      const matches = pathStr.match(/M[^M]+/gi);
      if (matches && matches.length > 0) {
        allDisaggregatedSubpaths.push(...matches);
      } else {
        allDisaggregatedSubpaths.push(pathStr);
      }
    });

    const singleSubpaths = deduplicateRibbonSubpaths(allDisaggregatedSubpaths);

    const flowerSvgIdx = ((idx - 1) % FLOWER_SVG_DATA_15.length) + 1;
    const flowerTransform = FLOWER_CUSTOM_TRANSFORMS[flowerSvgIdx] || FLOWER_CUSTOM_TRANSFORMS[idx] || "translate(15.16, 12.42) scale(0.42)";

    const shapes: MandalaShape[] = [
      ...singleSubpaths.map((pathD, pIdx) => ({
        id: `${id}_illustrator_path_${pIdx}`,
        type: "path" as const,
        d: pathD,
        transform: flowerTransform
      })),
      { id: `${id}_border_outer`, type: "circle", cx: 100, cy: 100, r: 94 }
    ];

    templates.push({
      id,
      title,
      shortTitle,
      desc,
      shapes
    });
  }

  return templates;
};

