const BUTTERFLY_TYPE_SLUGS = [
  "swallowtail", "monarch", "fairy", "celestial", "blossom",
  "rainbow", "silver", "nightfall", "starlight", "heart",
  "foliage", "silk", "sky", "ribbon", "moonlight"
];

export const BUTTERFLY_TYPES_LIST = Object.keys(mandalaNamesKo.butterflies.names).map((nameKey, idx) => ({
  name: nameKey,
  type: BUTTERFLY_TYPE_SLUGS[idx % BUTTERFLY_TYPE_SLUGS.length]
}));

const generateButterflyTemplates = (count: number): MandalaTemplate[] => {
  const templates: MandalaTemplate[] = [];

  const adjectives = mandalaNamesKo.butterflies.adjectives;
  const butterflyTypes = BUTTERFLY_TYPES_LIST;

  for (let idx = 1; idx <= count; idx++) {
    const bType = butterflyTypes[(idx - 1) % butterflyTypes.length];
    const adj = adjectives[(idx - 1) % adjectives.length];
    const id = `butterfly_${bType.type}_${idx}`;
    const shortTitle = `${adj} ${bType.name}`;
    const title = shortTitle;
    const desc = `2번째 온실을 자유롭게 배회하는 ${adj} ${bType.name} 만다라 도안 (no. ${idx})`;

    // Get raw path array, outer index, and transform for the current butterfly template (1.svg ~ 15.svg)
    const bItem = BUTTERFLY_SVG_DATA_15[(idx - 1) % BUTTERFLY_SVG_DATA_15.length] || { transform: "translate(15.16, 12.42) scale(0.41)", outerIndex: 0, subpaths: [] };
    const rawPaths = bItem.subpaths || [];

    // Filter out non-path strings like layer names or viewBox strings
    const validPaths = rawPaths.filter(pStr => pStr.startsWith("M") || pStr.startsWith("m"));

    // Disaggregate compound SVG paths into individual sub-paths for 100% fine-grained touch coloring
    const allDisaggregatedSubpaths: string[] = [];
    validPaths.forEach((pathStr) => {
      const matches = pathStr.match(/M[^M]+/gi);
      if (matches && matches.length > 0) {
        allDisaggregatedSubpaths.push(...matches);
      } else {
        allDisaggregatedSubpaths.push(pathStr);
      }
    });

    const singleSubpaths = deduplicateRibbonSubpaths(allDisaggregatedSubpaths);

    const butterflySvgIdx = ((idx - 1) % BUTTERFLY_SVG_DATA_15.length) + 1;
    const butterflyTransform = BUTTERFLY_CUSTOM_TRANSFORMS[butterflySvgIdx] || BUTTERFLY_CUSTOM_TRANSFORMS[idx] || "translate(15, 15) scale(0.4)";

    const shapes: MandalaShape[] = [
      ...singleSubpaths
        .filter((pathD) => !pathD.startsWith("M-0.") && !pathD.includes("c140,0,280,0,420,0")) // 나비 도안 사각형 배경 외곽 박스 제거
        .map((pathD, pIdx) => ({
          id: `${id}_illustrator_path_${pIdx}`,
          type: "path" as const,
          d: pathD,
          transform: butterflyTransform
        })),
      { id: `${id}_border_outer`, type: "circle", cx: 100, cy: 100, r: 94 }
    ];

    templates.push({
      id,
      title,
      shortTitle,
      desc,
      shapes
    });
  }

  return templates;
};

// ---------------------------------------------------------------------------
// BEE MANDALA GENERATOR (45 Unique Templates)
// ---------------------------------------------------------------------------

const createBeeHeadShapes = (id: string, seed: number): MandalaShape[] => {
  const shapes: MandalaShape[] = [];
  const headR = 10 + (seed % 4);
  const headCy = 46;

  // Head Base & Inner Mandala
  shapes.push({ id: `${id}_head_base`, type: "circle", cx: 100, cy: headCy, r: headR });
  shapes.push({ id: `${id}_head_inner`, type: "circle", cx: 100, cy: headCy, r: headR * 0.5 });
  shapes.push({ id: `${id}_head_center_dot`, type: "circle", cx: 100, cy: headCy, r: 2 });

  // Eyes (Symmetric)
  const eyeDx = headR * 0.55;
  shapes.push({ id: `${id}_eye_l`, type: "circle", cx: 100 - eyeDx, cy: headCy - 2, r: 2.5 });
  shapes.push({ id: `${id}_eye_r`, type: "circle", cx: 100 + eyeDx, cy: headCy - 2, r: 2.5 });

  // Antennae (Symmetric curves)
  const antCurve = 14 + (seed % 6);
  const antHeight = 18 + (seed % 6);
  shapes.push({
    id: `${id}_ant_l`,
    type: "path",
    d: `M${100 - 4},${headCy - 8} C${100 - 10},${headCy - antHeight * 0.6} ${100 - antCurve},${headCy - antHeight} ${100 - antCurve - 6},${headCy - antHeight + 2}`
  });
  shapes.push({
    id: `${id}_ant_r`,
    type: "path",
    d: `M${100 + 4},${headCy - 8} C${100 + 10},${headCy - antHeight * 0.6} ${100 + antCurve},${headCy - antHeight} ${100 + antCurve + 6},${headCy - antHeight + 2}`
  });

  // Antenna tips / Jewels
  const tipX = antCurve + 6;
  const tipY = headCy - antHeight + 2;
  shapes.push({ id: `${id}_ant_tip_l`, type: "circle", cx: 100 - tipX, cy: tipY, r: 3 });
  shapes.push({ id: `${id}_ant_tip_r`, type: "circle", cx: 100 + tipX, cy: tipY, r: 3 });

  // Crown / Halo (Queen or Fairy Bee style)
  if (seed % 3 === 0) {
    shapes.push({
      id: `${id}_crown`,
      type: "path",
      d: `M92,${headCy - 9} L95,${headCy - 18} L100,${headCy - 13} L105,${headCy - 18} L108,${headCy - 9} Z`
    });
    shapes.push({ id: `${id}_crown_gem`, type: "circle", cx: 100, cy: headCy - 20, r: 2.5 });
  }

  return shapes;
};

const createBeeBodyShapes = (id: string, seed: number): MandalaShape[] => {
  const shapes: MandalaShape[] = [];

  // 1. Thorax (가슴)
  const thoraxR = 14 + (seed % 4);
  const thoraxCy = 68;
  shapes.push({ id: `${id}_thorax_outer`, type: "circle", cx: 100, cy: thoraxCy, r: thoraxR });
  shapes.push({ id: `${id}_thorax_inner`, type: "circle", cx: 100, cy: thoraxCy, r: thoraxR * 0.6 });

  // Thorax Mandala Rosette (8-way spoke/petals inside thorax)
  const petalCount = 6 + ((seed % 3) * 2);
  const angleStep = 360 / petalCount;
  for (let i = 0; i < petalCount; i++) {
    shapes.push({
      id: `${id}_thorax_petal_${i}`,
      type: "path",
      d: `M100,${thoraxCy - 2} C96,${thoraxCy - thoraxR + 3} 104,${thoraxCy - thoraxR + 3} 100,${thoraxCy - 2} Z`,
      transform: `rotate(${i * angleStep}, 100, ${thoraxCy})`
    });
  }

  // 2. Abdomen Contour (배 실루엣)
  const abTop = 80;
  const abBot = 136 + (seed % 6);
  shapes.push({
    id: `${id}_abdomen_outline`,
    type: "path",
    d: `M${100 - 18},${abTop} C${100 - 28},${abTop + 24} ${100 - 22},${abBot - 10} 100,${abBot} C${100 + 22},${abBot - 10} ${100 + 28},${abTop + 24} ${100 + 18},${abTop} Z`
  });

  // Stinger (침)
  shapes.push({
    id: `${id}_stinger`,
    type: "path",
    d: `M97,${abBot} L100,${abBot + 10} L103,${abBot} Z`
  });

  // 3. Abdomen Stripes & Mandala Patterns
  const stripeStyle = seed % 5;
  const stripeY1 = abTop + 14;
  const stripeY2 = abTop + 28;
  const stripeY3 = abTop + 42;

  // Stripe Bands
  shapes.push({
    id: `${id}_stripe_band_1`,
    type: "path",
    d: `M${100 - 22},${stripeY1} Q100,${stripeY1 + 8} ${100 + 22},${stripeY1}`
  });
  shapes.push({
    id: `${id}_stripe_band_2`,
    type: "path",
    d: `M${100 - 21},${stripeY2} Q100,${stripeY2 + 8} ${100 + 21},${stripeY2}`
  });
  shapes.push({
    id: `${id}_stripe_band_3`,
    type: "path",
    d: `M${100 - 16},${stripeY3} Q100,${stripeY3 + 6} ${100 + 16},${stripeY3}`
  });

  // Mandala Fill Inside Abdomen
  if (stripeStyle === 0) {
    // Honeycomb Mesh pattern inside abdomen
    shapes.push({ id: `${id}_hex_c`, type: "path", d: "M96,98 L100,94 L104,98 L104,106 L100,110 L96,106 Z" });
    shapes.push({ id: `${id}_hex_l`, type: "path", d: "M86,98 L90,94 L94,98 L94,106 L90,110 L86,106 Z" });
    shapes.push({ id: `${id}_hex_r`, type: "path", d: "M106,98 L110,94 L114,98 L114,106 L110,110 L106,106 Z" });
    shapes.push({ id: `${id}_hex_b`, type: "path", d: "M96,112 L100,108 L104,112 L104,120 L100,124 L96,120 Z" });
  } else if (stripeStyle === 1) {
    // Scalloped Lace Stripes
    shapes.push({
      id: `${id}_scallop_1`,
      type: "path",
      d: `M80,94 Q85,100 90,94 Q95,100 100,94 Q105,100 110,94 Q115,100 120,94`
    });
    shapes.push({
      id: `${id}_scallop_2`,
      type: "path",
      d: `M82,108 Q87,114 92,108 Q97,114 102,108 Q107,114 112,108 Q117,114 118,108`
    });
  } else if (stripeStyle === 2) {
    // Dot Matrix & Gem Line
    for (let dx = -14; dx <= 14; dx += 7) {
      shapes.push({ id: `${id}_ab_dot1_${dx}`, type: "circle", cx: 100 + dx, cy: stripeY1 + 4, r: 2 });
      shapes.push({ id: `${id}_ab_dot2_${dx}`, type: "circle", cx: 100 + dx, cy: stripeY2 + 4, r: 2 });
    }
  } else if (stripeStyle === 3) {
    // Central Petal Medallion
    const medCy = (stripeY1 + stripeY3) / 2;
    shapes.push({ id: `${id}_ab_medallion_c`, type: "circle", cx: 100, cy: medCy, r: 7 });
    for (let i = 0; i < 4; i++) {
      shapes.push({
        id: `${id}_ab_med_petal_${i}`,
        type: "path",
        d: `M100,${medCy - 10} C96,${medCy - 4} 96,${medCy + 4} 100,${medCy + 10} C104,${medCy + 4} 104,${medCy - 4} 100,${medCy - 10} Z`,
        transform: `rotate(${i * 45}, 100, ${medCy})`
      });
    }
  } else {
    // Diamond Zigzag Stripes
    shapes.push({
      id: `${id}_zigzag`,
      type: "path",
      d: `M80,94 L86,102 L92,94 L98,102 L104,94 L110,102 L116,94 L120,102`
    });
    shapes.push({ id: `${id}_ab_center_star`, type: "path", d: "M100,108 L103,114 L109,114 L104,118 L106,124 L100,120 L94,124 L96,118 L91,114 L97,114 Z" });
  }

  return shapes;
};

const createBeeWingShapes = (id: string, seed: number): MandalaShape[] => {
  const shapes: MandalaShape[] = [];

  const wingSpan = 42 + (seed % 16);
  const patternType = seed % 5;

  // 1. Forewing Outline (상단 날개 - 좌우 대칭)
  // Left Forewing
  shapes.push({
    id: `${id}_forewing_l`,
    type: "path",
    d: `M${100 - 10},62 C${100 - 32},30 ${100 - wingSpan},18 ${100 - wingSpan + 10},48 C${100 - wingSpan + 22},70 ${100 - 24},72 ${100 - 10},62 Z`
  });
  // Right Forewing
  shapes.push({
    id: `${id}_forewing_r`,
    type: "path",
    d: `M${100 + 10},62 C${100 + 32},30 ${100 + wingSpan},18 ${100 + wingSpan - 10},48 C${100 + wingSpan - 22},70 ${100 + 24},72 ${100 + 10},62 Z`
  });

  // 2. Hindwing Outline (하단 날개 - 좌우 대칭)
  // Left Hindwing
  shapes.push({
    id: `${id}_hindwing_l`,
    type: "path",
    d: `M${100 - 12},72 C${100 - 32},68 ${100 - wingSpan + 14},80 ${100 - wingSpan + 26},96 C${100 - wingSpan + 36},106 ${100 - 20},90 ${100 - 12},72 Z`
  });
  // Right Hindwing
  shapes.push({
    id: `${id}_hindwing_r`,
    type: "path",
    d: `M${100 + 12},72 C${100 + 32},68 ${100 + wingSpan - 14},80 ${100 + wingSpan - 26},96 C${100 + wingSpan - 36},106 ${100 + 20},90 ${100 + 12},72 Z`
  });

  // 3. Internal Wing Mandala Patterns (5 Different Unique Styles)
  const wingCenterX_l = 100 - wingSpan * 0.52;
  const wingCenterX_r = 100 + wingSpan * 0.52;

  if (patternType === 0) {
    // Honeycomb Grid Motif in Forewings
    shapes.push({ id: `${id}_wing_hex_l1`, type: "path", d: `M${wingCenterX_l - 6},44 L${wingCenterX_l},40 L${wingCenterX_l + 6},44 L${wingCenterX_l + 6},52 L${wingCenterX_l},56 L${wingCenterX_l - 6},52 Z` });
    shapes.push({ id: `${id}_wing_hex_r1`, type: "path", d: `M${wingCenterX_r - 6},44 L${wingCenterX_r},40 L${wingCenterX_r + 6},44 L${wingCenterX_r + 6},52 L${wingCenterX_r},56 L${wingCenterX_r - 6},52 Z` });
    shapes.push({ id: `${id}_wing_hex_l2`, type: "path", d: `M${wingCenterX_l - 16},44 L${wingCenterX_l - 10},40 L${wingCenterX_l - 4},44 L${wingCenterX_l - 4},52 L${wingCenterX_l - 10},56 L${wingCenterX_l - 16},52 Z` });
    shapes.push({ id: `${id}_wing_hex_r2`, type: "path", d: `M${wingCenterX_r + 4},44 L${wingCenterX_r + 10},40 L${wingCenterX_r + 16},44 L${wingCenterX_r + 16},52 L${wingCenterX_r + 10},56 L${wingCenterX_r + 4},52 Z` });
  } else if (patternType === 1) {
    // Concentric Arcs & Radial Rays
    shapes.push({ id: `${id}_w_arc_l1`, type: "path", d: `M${100 - 18},54 Q${wingCenterX_l},34 ${100 - wingSpan + 8},48` });
    shapes.push({ id: `${id}_w_arc_r1`, type: "path", d: `M${100 + 18},54 Q${wingCenterX_r},34 ${100 + wingSpan - 8},48` });
    shapes.push({ id: `${id}_w_arc_l2`, type: "path", d: `M${100 - 18},60 Q${wingCenterX_l},42 ${100 - wingSpan + 14},56` });
    shapes.push({ id: `${id}_w_arc_r2`, type: "path", d: `M${100 + 18},60 Q${wingCenterX_r},42 ${100 + wingSpan - 14},56` });
    shapes.push({ id: `${id}_w_dot_l`, type: "circle", cx: wingCenterX_l, cy: 46, r: 4 });
    shapes.push({ id: `${id}_w_dot_r`, type: "circle", cx: wingCenterX_r, cy: 46, r: 4 });
  } else if (patternType === 2) {
    // Mandala Flower Rosette overlay
    shapes.push({ id: `${id}_w_flower_l`, type: "circle", cx: wingCenterX_l, cy: 46, r: 6 });
    shapes.push({ id: `${id}_w_flower_r`, type: "circle", cx: wingCenterX_r, cy: 46, r: 6 });
    for (let i = 0; i < 4; i++) {
      shapes.push({
        id: `${id}_w_fl_petal_l_${i}`,
        type: "path",
        d: `M${wingCenterX_l},40 C${wingCenterX_l - 4},34 ${wingCenterX_l + 4},34 ${wingCenterX_l},40 Z`,
        transform: `rotate(${i * 90}, ${wingCenterX_l}, 46)`
      });
      shapes.push({
        id: `${id}_w_fl_petal_r_${i}`,
        type: "path",
        d: `M${wingCenterX_r},40 C${wingCenterX_r - 4},34 ${wingCenterX_r + 4},34 ${wingCenterX_r},40 Z`,
        transform: `rotate(${i * 90}, ${wingCenterX_r}, 46)`
      });
    }
  } else if (patternType === 3) {
    // Vein Lattice Mesh & Dots
    shapes.push({ id: `${id}_w_vein_l1`, type: "path", d: `M${100 - 10},62 L${100 - wingSpan + 10},48` });
    shapes.push({ id: `${id}_w_vein_r1`, type: "path", d: `M${100 + 10},62 L${100 + wingSpan - 10},48` });
    shapes.push({ id: `${id}_w_vein_l2`, type: "path", d: `M${100 - 20},48 L${100 - wingSpan + 18},62` });
    shapes.push({ id: `${id}_w_vein_r2`, type: "path", d: `M${100 + 20},48 L${100 + wingSpan - 18},62` });
    shapes.push({ id: `${id}_w_spot_l1`, type: "circle", cx: wingCenterX_l, cy: 40, r: 3 });
    shapes.push({ id: `${id}_w_spot_r1`, type: "circle", cx: wingCenterX_r, cy: 40, r: 3 });
  } else {
    // Paisley Teardrop Loop
    shapes.push({
      id: `${id}_w_paisley_l`,
      type: "path",
      d: `M${100 - 20},58 C${wingCenterX_l - 8},38 ${wingCenterX_l + 8},38 ${100 - wingSpan + 16},50 C${wingCenterX_l},62 ${100 - 22},64 ${100 - 20},58 Z`
    });
    shapes.push({
      id: `${id}_w_paisley_r`,
      type: "path",
      d: `M${100 + 20},58 C${wingCenterX_r + 8},38 ${wingCenterX_r - 8},38 ${100 + wingSpan - 16},50 C${wingCenterX_r},62 ${100 + 22},64 ${100 + 20},58 Z`
    });
  }

  // Hindwing Center Spot
  shapes.push({ id: `${id}_hw_spot_l`, type: "circle", cx: 100 - wingSpan * 0.45, cy: 84, r: 4 });
  shapes.push({ id: `${id}_hw_spot_r`, type: "circle", cx: 100 + wingSpan * 0.45, cy: 84, r: 4 });

  return shapes;
};

const generateBeeBirdTemplates = (count: number = 45): MandalaTemplate[] => {
  const templates: MandalaTemplate[] = [];

  const adjectives = mandalaNamesKo.creatures.adjectives;

  for (let idx = 1; idx <= count; idx++) {
    const item = BEE_BIRD_SVG_DATA_15[(idx - 1) % BEE_BIRD_SVG_DATA_15.length] || { name: "생명체", type: "bee", transform: "translate(38.36, 43.31) scale(0.3682)", outerIndex: 0, subpaths: [] };
    const adj = adjectives[(idx - 1) % adjectives.length];
    const isBee = item.type === 'bee';
    const idPrefix = isBee ? 'bee' : 'bird';
    const id = `beebird_${idPrefix}_${idx}`;
    const shortTitle = `${adj} ${item.name}`;
    const title = shortTitle;
    const desc = `3번째 온실을 자유롭게 배회하는 ${adj} ${item.name} 만다라 도안 (no. ${idx})`;

    const rawPaths = item.subpaths || [];
    const validPaths = rawPaths.filter(pStr => pStr.startsWith("M") || pStr.startsWith("m"));

    const allDisaggregatedSubpaths: string[] = [];
    validPaths.forEach((pathStr) => {
      const matches = pathStr.match(/M[^M]+/gi);
      if (matches && matches.length > 0) {
        allDisaggregatedSubpaths.push(...matches);
      } else {
        allDisaggregatedSubpaths.push(pathStr);
      }
    });

    const singleSubpaths = deduplicateRibbonSubpaths(allDisaggregatedSubpaths);

    const beeBirdSvgIdx = ((idx - 1) % BEE_BIRD_SVG_DATA_15.length) + 1;
    const beeBirdTransform = BEE_BIRD_CUSTOM_TRANSFORMS[beeBirdSvgIdx] || BEE_BIRD_CUSTOM_TRANSFORMS[idx] || "translate(12, 11) scale(0.42)";

    const shapes: MandalaShape[] = [
      ...singleSubpaths.map((pathD, pIdx) => ({
        id: (item.type === 'bee' && pIdx === item.outerIndex)
          ? (beeBirdSvgIdx === 1 ? `${id}_illustrator_path_${pIdx}_outline_notouch` : `${id}_illustrator_path_${pIdx}_notouch`)  // bee 1번만 외곽 검은색 처리, 나머지는 색상 유지(클릭 불가)
          : `${id}_illustrator_path_${pIdx}`,
        type: "path" as const,
        d: pathD,
        transform: beeBirdTransform
      })),
      { id: `${id}_border_outer`, type: "circle", cx: 100, cy: 100, r: 94 }
    ];

    templates.push({ id, title, shortTitle, desc, shapes });
  }

  return templates;
};

const generateBeeTemplates = generateBeeBirdTemplates;


