const createBirdHeadShapes = (id: string, seed: number): MandalaShape[] => {
  const shapes: MandalaShape[] = [];
  const headCy = 42;
  const headR = 12 + (seed % 3);

  // Head Base
  shapes.push({ id: `${id}_head_base`, type: "circle", cx: 100, cy: headCy, r: headR });
  shapes.push({ id: `${id}_head_inner`, type: "circle", cx: 100, cy: headCy, r: headR * 0.55 });

  // Eyes & Eye Line
  shapes.push({ id: `${id}_eye_l`, type: "circle", cx: 94, cy: headCy - 2, r: 2.5 });
  shapes.push({ id: `${id}_eye_r`, type: "circle", cx: 106, cy: headCy - 2, r: 2.5 });
  shapes.push({ id: `${id}_eyeline_l`, type: "path", d: `M90,${headCy - 2} Q94,${headCy - 6} 98,${headCy - 2}` });
  shapes.push({ id: `${id}_eyeline_r`, type: "path", d: `M102,${headCy - 2} Q106,${headCy - 6} 110,${headCy - 2}` });

  // Beak (부리)
  shapes.push({ id: `${id}_beak_upper`, type: "path", d: `M95,${headCy + 3} L100,${headCy + 14} L105,${headCy + 3} Z` });
  shapes.push({ id: `${id}_beak_line`, type: "path", d: `M97,${headCy + 3} L100,${headCy + 11} L103,${headCy + 3}` });

  // Crest / Feathers on Head (벼슬 장식 4가지 스타일)
  const crestStyle = seed % 4;
  if (crestStyle === 0) {
    // 3-Feather Crown
    shapes.push({ id: `${id}_crest_c`, type: "path", d: `M100,${headCy - headR} C96,16 104,16 100,${headCy - headR} Z` });
    shapes.push({ id: `${id}_crest_l`, type: "path", d: `M96,${headCy - headR + 2} C88,20 94,18 96,${headCy - headR + 2} Z` });
    shapes.push({ id: `${id}_crest_r`, type: "path", d: `M104,${headCy - headR + 2} C112,20 106,18 104,${headCy - headR + 2} Z` });
  } else if (crestStyle === 1) {
    // Sun Halo Arc
    shapes.push({ id: `${id}_crest_halo`, type: "path", d: `M86,${headCy - 4} Q100,${headCy - headR - 12} 114,${headCy - 4}` });
    shapes.push({ id: `${id}_crest_gem_c`, type: "circle", cx: 100, cy: headCy - headR - 6, r: 3 });
  } else if (crestStyle === 2) {
    // Graceful Loop Feathers
    shapes.push({ id: `${id}_crest_loop_l`, type: "path", d: `M97,${headCy - headR} C85,14 78,28 94,${headCy - headR + 4}` });
    shapes.push({ id: `${id}_crest_loop_r`, type: "path", d: `M103,${headCy - headR} C115,14 122,28 106,${headCy - headR + 4}` });
  } else {
    // Jewel Crest Tips
    shapes.push({ id: `${id}_crest_spire`, type: "path", d: `M98,${headCy - headR} L100,18 L102,${headCy - headR} Z` });
    shapes.push({ id: `${id}_crest_jewel`, type: "circle", cx: 100, cy: 15, r: 3.5 });
  }

  return shapes;
};

