export const getLocalizedTemplateInfo = (id: string, en: boolean): { title: string; desc: string } => {
  const namesData = en ? mandalaNamesEn : mandalaNamesKo;

  if (id.startsWith('flower_')) {
    const idx = parseInt(id.replace('flower_', ''), 10) || 1;
    const fItem = FLOWER_SVG_DATA_15[(idx - 1) % FLOWER_SVG_DATA_15.length] || { flowerName: "연꽃" };
    const rawName = (fItem.flowerName || "연꽃").replace(/\s*\d+$/, '');
    const adjList = namesData.flowers.adjectives;
    const adj = adjList[(idx - 1) % adjList.length];
    const nameMap = namesData.flowers.names as Record<string, string>;
    const flowerName = nameMap[rawName] || rawName;
    const title = `${adj} ${flowerName}`;
    const desc = en
      ? `Mandala design of ${adj} ${flowerName} to cleanse inner feelings in the 1st Greenhouse (no. ${idx})`
      : `1번째 온실에서 내면의 평화와 감정을 정화하는 ${adj} ${flowerName} 꽃 도안 (no. ${idx})`;
    return { title, desc };
  }

  if (id.startsWith('butterfly_')) {
    const parts = id.split('_');
    const idx = parseInt(parts[parts.length - 1], 10) || 1;
    const bType = BUTTERFLY_TYPES_LIST[(idx - 1) % BUTTERFLY_TYPES_LIST.length];
    const adjList = namesData.butterflies.adjectives;
    const adj = adjList[(idx - 1) % adjList.length];
    const nameMap = namesData.butterflies.names as Record<string, string>;
    const butterflyName = nameMap[bType.name] || bType.name;
    const title = `${adj} ${butterflyName}`;
    const desc = en
      ? `Mandala design of ${adj} ${butterflyName} roaming freely in the 2nd Greenhouse (no. ${idx})`
      : `2번째 온실을 자유롭게 배회하는 ${adj} ${butterflyName} 만다라 도안 (no. ${idx})`;
    return { title, desc };
  }

  if (id.startsWith('beebird_')) {
    const parts = id.split('_');
    const idx = parseInt(parts[parts.length - 1], 10) || 1;
    const item = BEE_BIRD_SVG_DATA_15[(idx - 1) % BEE_BIRD_SVG_DATA_15.length] || { name: "생명체", type: "bee" };
    const adjList = namesData.creatures.adjectives;
    const adj = adjList[(idx - 1) % adjList.length];
    const nameMap = namesData.creatures.names as Record<string, string>;
    const creatureName = nameMap[item.name] || item.name;
    const title = `${adj} ${creatureName}`;
    const desc = en
      ? `Mandala design of ${adj} ${creatureName} roaming freely in the 3rd Greenhouse (no. ${idx})`
      : `3번째 온실을 자유롭게 배회하는 ${adj} ${creatureName} 만다라 도안 (no. ${idx})`;
    return { title, desc };
  }

  return {
    title: id,
    desc: ''
  };
};

export const getTemplateById = (id: string): MandalaTemplate => {
  const base =
    ALL_MANDALA_20.find(t => t.id === id) ||
    ALL_BUTTERFLY_MANDALA_45.find(t => t.id === id) ||
    ALL_BEE_BIRD_MANDALA_45.find(t => t.id === id) ||
    ALL_BEE_MANDALA_45.find(t => t.id === id) ||
    ALL_BIRD_MANDALA_45.find(t => t.id === id) ||
    ALL_MANDALA_20[0];

  const info = getLocalizedTemplateInfo(base.id, isEn());
  return {
    ...base,
    title: info.title,
    shortTitle: info.title,
    desc: info.desc
  };
};

